    dump(root/"agents/relay/execution-packages/EP-B1.yaml",ep1);dump(root/"agents/relay/execution-packages/EP-B2.yaml",ep2)
    new_plan={"schema_version":"relay-v2.5","id":"PLAN-P2","previous_replan":"REPLAN-P2","previous_replan_path":"agents/relay/parallel/REPLAN-P2.yaml","owner_approval":{"approved":True,"authority":"OWNER","source":"OWNER-DECISION-2","approval_token":"APPROVE PARALLEL PLAN-P2"},"ascii_topology":"REPLAN\n +-- B1\n +-- B2\n  \\ /\n INTEGRATE-2","lanes":[{"id":"LANE-B1","state":"ACTIVE","work_package":"WP-B1","ep_id":"EP-B1","ep_path":"agents/relay/execution-packages/EP-B1.yaml","branch":"agent/lane-b1","worktree":"wt-b1","write_domains":["src/b1"],"shared_read_domains":["src/shared"]},{"id":"LANE-B2","state":"ACTIVE","work_package":"WP-B2","ep_id":"EP-B2","ep_path":"agents/relay/execution-packages/EP-B2.yaml","branch":"agent/lane-b2","worktree":"wt-b2","write_domains":["src/b2"],"shared_read_domains":["src/shared"]}],"shared_write_exceptions":[],"integration":{"owner":"OWNER","work_package":"WP-I2","planned_ep_id":"EP-I2","creation_policy":"WHEN_FRONTIER","depends_on_lanes":["LANE-B1","LANE-B2"]},"risks":[{"id":"R2","description":"replacement-lane integration risk"}],"stop_conditions":[{"id":"S2","condition":"replacement lane leaves approved write domain"}]};dump(root/"agents/relay/parallel/PLAN-P2.yaml",new_plan)
    receipt={"schema_version":"relay-v2.5-parallel-replan","id":"REPLAN-P2","predecessor_plan":{"id":"PLAN-P1","path":"agents/relay/parallel/PLAN-P1.yaml"},"trigger":{"type":"LANE_INVALIDATED","lane_id":"LANE-B","reason":"Lane B must split into two independently isolated replacement packages.","basis":["ROADMAP-REVISION-RM-2"]},"lane_dispositions":[{"lane_id":"LANE-A","work_package":"WP-A","disposition":"COMPLETE","checkpoint":{"id":"CP-A","path":"agents/relay/checkpoints/CP-A.yaml"}},{"lane_id":"LANE-B","work_package":"WP-B","disposition":"INVALIDATED","basis":["ROADMAP-REVISION-RM-2"],"unresolved_acceptance":copy.deepcopy(all_acc),"evidence":copy.deepcopy(all_ev),"transfers":[{"work_package":"WP-B1","unresolved_acceptance":copy.deepcopy([acc1]),"evidence":copy.deepcopy([ev1])},{"work_package":"WP-B2","unresolved_acceptance":copy.deepcopy([acc2]),"evidence":copy.deepcopy([ev2])}]}],"roadmap_reconciliation":{"roadmap_revision":"RM-1","frontier_after":["WP-B1","WP-B2"]},"successor_route":{"mode":"PARALLEL","work_package":None,"ep_id":None,"ep_path":None,"parallel_plan_id":"PLAN-P2","parallel_plan_path":"agents/relay/parallel/PLAN-P2.yaml"}};dump(root/"agents/relay/parallel/REPLAN-P2.yaml",receipt)
