class ParallelReplanStressTests(unittest.TestCase):
    def test_partial_lane_invalidation_can_collapse_to_one_serial_replacement(self):
        with tempfile.TemporaryDirectory() as td:root=Path(td);serial_replan_repo(root);self.assertEqual([],parallel_replan(root)[0])
    def test_completed_sibling_checkpoint_cannot_disappear_from_replan(self):
        with tempfile.TemporaryDirectory() as td:root=Path(td);receipt,_=serial_replan_repo(root);receipt["lane_dispositions"]=receipt["lane_dispositions"][1:];dump(root/"agents/relay/parallel/REPLAN-P2.yaml",receipt);self.assertTrue(any("cover every predecessor lane" in x for x in parallel_replan(root)[0]))
    def test_replacement_ep_must_inherit_invalidated_acceptance_and_evidence_exactly(self):
        with tempfile.TemporaryDirectory() as td:root=Path(td);_,replacement=serial_replan_repo(root);replacement["replan_inheritance"]["evidence"][0]["status"]="PASS";dump(root/"agents/relay/execution-packages/EP-B2.yaml",replacement);self.assertTrue(any("inheritance mismatch for evidence" in x for x in parallel_replan(root)[0]))
    def test_replanned_ep_has_one_predecessor_baton(self):
        with tempfile.TemporaryDirectory() as td:root=Path(td);_,replacement=serial_replan_repo(root);replacement["identity"]["previous_checkpoint"]="CP-A";errors=validate_ep_data(root,replacement,"replacement")[0];self.assertTrue(any("only one of previous_checkpoint, previous_join, previous_replan" in x for x in errors))
    def test_invalidated_lane_can_split_exactly_into_new_parallel_frontier(self):
        with tempfile.TemporaryDirectory() as td:root=Path(td);parallel_replan_repo(root);self.assertEqual([],parallel_replan(root)[0]);self.assertEqual([],parallel_plan(root)[0])
    def test_split_transfer_cannot_duplicate_unresolved_evidence(self):
        with tempfile.TemporaryDirectory() as td:root=Path(td);receipt,_,_,_=parallel_replan_repo(root);bad=receipt["lane_dispositions"][1]["transfers"];bad[1]["evidence"]=[copy.deepcopy(bad[0]["evidence"][0])];dump(root/"agents/relay/parallel/REPLAN-P2.yaml",receipt);self.assertTrue(any("evidence transfer partition" in x for x in parallel_replan(root)[0]))
    def test_split_transfer_cannot_upgrade_not_run_to_pass(self):
        with tempfile.TemporaryDirectory() as td:root=Path(td);receipt,_,_,_=parallel_replan_repo(root);receipt["lane_dispositions"][1]["transfers"][0]["evidence"][0]["status"]="PASS";dump(root/"agents/relay/parallel/REPLAN-P2.yaml",receipt);self.assertTrue(any("evidence transfer partition" in x for x in parallel_replan(root)[0]))
    def test_new_parallel_plan_and_lanes_must_bind_replan(self):
        with tempfile.TemporaryDirectory() as td:root=Path(td);_,plan,ep1,_=parallel_replan_repo(root);plan.pop("previous_replan");plan.pop("previous_replan_path");dump(root/"agents/relay/parallel/PLAN-P2.yaml",plan);self.assertTrue(any("previous_replan" in x for x in parallel_plan(root)[0]));ep1["identity"].pop("previous_replan");dump(root/"agents/relay/execution-packages/EP-B1.yaml",ep1);self.assertTrue(any("previous_replan" in x for x in parallel_replan(root)[0]))

if __name__=="__main__":unittest.main()
